/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test (via dotenv) at startup and creates a
 * managed pg.Pool instance.  Never hard-code credential values here; always
 * source them from the environment so secrets stay out of source control.
 *
 * Usage
 * -----
 *   const db = require('./db');
 *
 *   // Run a query
 *   const { rows } = await db.query('SELECT $1::text AS message', ['hello']);
 *
 *   // Check connectivity
 *   const healthy = await db.healthCheck();
 *
 *   // Drain the pool on shutdown
 *   await db.end();
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1.  Load environment variables from .env.test
//     override: true  — values in .env.test take precedence over any
//                        variables that were already set in process.env,
//                        which is important in test environments where a
//                        prior .env might already be loaded.
// ---------------------------------------------------------------------------
const envPath = path.resolve(__dirname, '.env.test');
const envResult = dotenv.config({ path: envPath, override: true });

if (envResult.error) {
  // Non-fatal: warn but continue — DATABASE_URL may already be in the
  // environment (e.g. set by a CI/CD system).
  console.warn(
    `[db] Warning: could not load ${envPath} — ${envResult.error.message}`
  );
}

// ---------------------------------------------------------------------------
// 2.  Validate that the required variable is present before creating the pool
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
      'Ensure it is set in .env.test or in the process environment.'
  );
}

// ---------------------------------------------------------------------------
// 3.  Pool configuration
//
//     All tuning values have sensible defaults that work for most test and
//     small-production workloads.  Override them via environment variables
//     so that no code change is needed between environments.
// ---------------------------------------------------------------------------
const POOL_CONFIG = {
  connectionString: DATABASE_URL,

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client can sit idle before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait for a free client before throwing an error.
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '5000',
    10
  ),

  // Keeps TCP connections alive to prevent firewall/NAT drops.
  keepAlive: true,
};

// ---------------------------------------------------------------------------
// 4.  Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(POOL_CONFIG);

// ---------------------------------------------------------------------------
// 5.  Pool-level error handler
//
//     'error' events are emitted for problems that occur on an idle client
//     (e.g. the database server restarted while no query was running).
//     Without this listener the process would crash with an unhandled error.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  console.error('[db] Stack:', err.stack);
  // Do NOT call process.exit() here — let the application decide how to
  // handle the situation (retry, alert, graceful shutdown, etc.).
});

// Emit a log message each time a new physical connection is established so
// connection-count issues are easy to spot in logs.
pool.on('connect', () => {
  console.info('[db] New client connected to the pool.');
});

// Emit a log message when a client is returned to the pool.
pool.on('acquire', () => {
  console.debug('[db] Client acquired from pool.');
});

// ---------------------------------------------------------------------------
// 6.  Public API
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised SQL query using a pool client.
 *
 * The client is automatically released back to the pool after the query
 * completes or fails, so callers never need to manage clients directly for
 * simple queries.
 *
 * @param  {string}   text    - Parameterised SQL string, e.g. 'SELECT $1'
 * @param  {Array}   [params] - Positional parameter values (optional)
 * @returns {Promise<import('pg').QueryResult>}
 *
 * @example
 *   const { rows } = await db.query(
 *     'SELECT id, name FROM users WHERE active = $1',
 *     [true]
 *   );
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    console.debug(
      `[db] Query executed in ${duration}ms — rows returned: ${result.rowCount}`
    );

    return result;
  } catch (err) {
    const duration = Date.now() - start;
    console.error(`[db] Query failed after ${duration}ms:`, err.message);
    throw err; // Re-throw so the caller can handle it appropriately.
  }
}

/**
 * Check out a dedicated client from the pool for use within a transaction
 * or a sequence of related queries.
 *
 * IMPORTANT: the caller is responsible for calling client.release() when
 * finished — failing to do so will exhaust the pool.
 *
 * @returns {Promise<import('pg').PoolClient>}
 *
 * @example
 *   const client = await db.getClient();
 *   try {
 *     await client.query('BEGIN');
 *     await client.query('INSERT INTO ...', [...]);
 *     await client.query('COMMIT');
 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 */
async function getClient() {
  try {
    const client = await pool.connect();
    return client;
  } catch (err) {
    console.error('[db] Failed to acquire client from pool:', err.message);
    throw err;
  }
}

/**
 * Verify that the database is reachable and responding to queries.
 *
 * Runs `SELECT 1` inside a short-lived connection acquired from the pool.
 * The function is intentionally non-throwing: it always resolves so that
 * health-check endpoints can report status without crashing.
 *
 * @returns {Promise<{
 *   healthy: boolean,
 *   timestamp: string,
 *   responseTimeMs: number,
 *   poolStats: { total: number, idle: number, waiting: number },
 *   error: string|null
 * }>}
 *
 * @example
 *   app.get('/health/db', async (req, res) => {
 *     const status = await db.healthCheck();
 *     res.status(status.healthy ? 200 : 503).json(status);
 *   });
 */
async function healthCheck() {
  const start = Date.now();

  const poolStats = {
    total: pool.totalCount,
    idle: pool.idleCount,
    waiting: pool.waitingCount,
  };

  try {
    await pool.query('SELECT 1');

    const responseTimeMs = Date.now() - start;

    const result = {
      healthy: true,
      timestamp: new Date().toISOString(),
      responseTimeMs,
      poolStats,
      error: null,
    };

    console.info(
      `[db] Health check passed in ${responseTimeMs}ms. Pool — ` +
        `total: ${poolStats.total}, idle: ${poolStats.idle}, ` +
        `waiting: ${poolStats.waiting}`
    );

    return result;
  } catch (err) {
    const responseTimeMs = Date.now() - start;

    const result = {
      healthy: false,
      timestamp: new Date().toISOString(),
      responseTimeMs,
      poolStats,
      error: err.message,
    };

    console.error(
      `[db] Health check failed after ${responseTimeMs}ms: ${err.message}`
    );

    return result;
  }
}

/**
 * Gracefully drain and close all pool connections.
 *
 * Call this during application shutdown (SIGTERM/SIGINT handlers) to prevent
 * connection leaks.  Subsequent calls to query() will throw once the pool is
 * ended.
 *
 * @returns {Promise<void>}
 *
 * @example
 *   process.on('SIGTERM', async () => {
 *     await db.end();
 *     process.exit(0);
 *   });
 */
async function end() {
  try {
    await pool.end();
    console.info('[db] Connection pool closed successfully.');
  } catch (err) {
    console.error('[db] Error while closing connection pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 7.  Module exports
// ---------------------------------------------------------------------------
module.exports = {
  /** Run a one-off parameterised query. */
  query,
  /** Acquire a dedicated client (remember to release() it). */
  getClient,
  /** Non-throwing connectivity + pool-stats check. */
  healthCheck,
  /** Drain the pool — call on process shutdown. */
  end,
  /**
   * Expose the underlying Pool instance for advanced use-cases
   * (e.g. streaming queries, COPY protocol).
   * Prefer the helper functions above for normal usage.
   */
  pool,
};

