/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL at runtime from .env.test (via dotenv) and exposes:
 *   pool      — the pg Pool instance for direct query use
 *   query()   — thin wrapper that acquires/releases a client automatically
 *   healthCheck() — verifies the pool can reach the database
 *   closePool()   — drains the pool (useful in tests / graceful shutdown)
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op for keys that are already set in process.env,
//    so this is safe to call in any environment without overwriting CI secrets.
// ---------------------------------------------------------------------------
require('dotenv').config({ path: path.resolve(__dirname, '.env.test') });

// ---------------------------------------------------------------------------
// 2. Validate that DATABASE_URL is present before trying to connect
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
      'Ensure .env.test exists and contains a valid DATABASE_URL entry.'
  );
}

// ---------------------------------------------------------------------------
// 3. Build the connection pool
//
//    Pool options are intentionally conservative so the module works for both
//    small local setups and modest production workloads. Override any of these
//    by setting the corresponding pg environment variables (PGPOOL_MAX, etc.)
//    or by editing the options object below.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.PGPOOL_MAX, 10) || 10,

  // Milliseconds a client can sit idle before being closed.
  idleTimeoutMillis: parseInt(process.env.PGPOOL_IDLE_TIMEOUT, 10) || 30_000,

  // Milliseconds to wait for a connection before throwing a timeout error.
  connectionTimeoutMillis:
    parseInt(process.env.PGPOOL_CONNECT_TIMEOUT, 10) || 5_000,

  // Allow the pool to stay alive even after the event-loop would otherwise exit.
  // Set to false in long-running servers; true is friendlier for short scripts.
  allowExitOnIdle: process.env.PGPOOL_ALLOW_EXIT_ON_IDLE !== 'false',
});

// ---------------------------------------------------------------------------
// 4. Pool-level error handler
//
//    pg emits an 'error' event on the pool when a connected (but idle) client
//    encounters an unexpected error (e.g. the server closed the connection).
//    Without this listener Node.js would throw an uncaught exception and crash.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw here — the pool will automatically remove the broken
  // client and replace it on the next acquire() call.
});

// ---------------------------------------------------------------------------
// 5. Optional lifecycle logging (enabled when NODE_ENV !== 'production')
// ---------------------------------------------------------------------------
if (process.env.NODE_ENV !== 'production') {
  pool.on('connect', () => {
    console.debug('[db] New client connected to the pool.');
  });

  pool.on('acquire', () => {
    console.debug(
      `[db] Client acquired. Pool size: ${pool.totalCount} | ` +
        `idle: ${pool.idleCount} | waiting: ${pool.waitingCount}`
    );
  });

  pool.on('remove', () => {
    console.debug('[db] Client removed from the pool.');
  });
}

// ---------------------------------------------------------------------------
// 6. query() — fire-and-forget helper
//
//    Usage:
//      const { rows } = await query('SELECT * FROM users WHERE id = $1', [42]);
//
//    The helper checks out a client, runs the query, then releases the client
//    back to the pool — even if the query throws.
// ---------------------------------------------------------------------------
async function query(text, params) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new TypeError('[db] query() requires a non-empty SQL string.');
  }

  const start = Date.now();

  try {
    const result = await pool.query(text, params);

    if (process.env.NODE_ENV !== 'production') {
      console.debug(
        `[db] Query executed in ${Date.now() - start} ms | ` +
          `rows: ${result.rowCount} | query: ${text.slice(0, 120)}`
      );
    }

    return result;
  } catch (err) {
    // Enrich the error with the query text before re-throwing so callers
    // get useful context without having to catch-and-inspect separately.
    err.query = text;
    console.error(
      `[db] Query failed after ${Date.now() - start} ms: ${err.message}`
    );
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 7. healthCheck() — liveness / readiness probe
//
//    Sends a trivial SELECT 1 to confirm end-to-end connectivity.
//    Returns an object so callers can distinguish healthy vs. unhealthy states
//    without relying on exception flow (handy for /healthz HTTP endpoints).
//
//    Usage:
//      const { healthy, latencyMs, error } = await healthCheck();
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();

  try {
    const { rows } = await pool.query('SELECT 1 AS ok');
    const latencyMs = Date.now() - start;

    if (rows[0]?.ok !== 1) {
      throw new Error('Unexpected response from database during health check.');
    }

    console.log(`[db] Health check passed (${latencyMs} ms).`);

    return {
      healthy: true,
      latencyMs,
      poolTotalCount: pool.totalCount,
      poolIdleCount: pool.idleCount,
      poolWaitingCount: pool.waitingCount,
      error: null,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;

    console.error(`[db] Health check failed (${latencyMs} ms): ${err.message}`);

    return {
      healthy: false,
      latencyMs,
      poolTotalCount: pool.totalCount,
      poolIdleCount: pool.idleCount,
      poolWaitingCount: pool.waitingCount,
      error: err.message,
    };
  }
}

// ---------------------------------------------------------------------------
// 8. closePool() — graceful shutdown
//
//    Drains the pool: waits for in-flight queries to finish, then closes every
//    idle client. Call this in SIGTERM / SIGINT handlers and after test suites.
//
//    Usage:
//      process.on('SIGTERM', async () => { await closePool(); process.exit(0); });
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[db] Closing connection pool…');

  try {
    await pool.end();
    console.log('[db] Connection pool closed.');
  } catch (err) {
    console.error('[db] Error while closing connection pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 9. Exports
// ---------------------------------------------------------------------------
module.exports = {
  pool,        // raw Pool — use when you need transactions or COPY streams
  query,       // single-query helper
  healthCheck, // liveness/readiness probe
  closePool,   // graceful drain
};

