{
  "name": "p15-test-pfd6e3",
  "version": "1.0.0",
  "description": "PostgreSQL connection pool module with health check",
  "main": "db.js",
  "scripts": {
    "test": "jest --runInBand --forceExit",
    "test:coverage": "jest --runInBand --forceExit --coverage"
  },
  "keywords": ["postgres", "pg", "database", "pool"],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "dotenv": "^16.4.5",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test (or whichever env file is loaded before
 * this module is imported) and exposes:
 *
 *   pool        — the raw pg.Pool instance for advanced use-cases
 *   query()     — a thin wrapper around pool.query() with error logging
 *   getClient() — checks out a client with automatic release on error
 *   healthCheck() — verifies the database is reachable
 *   closePool() — gracefully shuts the pool down (useful in tests / shutdown hooks)
 */

"use strict";

const path = require("path");

// ---------------------------------------------------------------------------
// 1.  Load environment variables from .env.test
//     dotenv.config() is a no-op when a variable is already set, so calling
//     it here is safe even if the caller has already loaded another .env file.
// ---------------------------------------------------------------------------
const dotenv = require("dotenv");

const envResult = dotenv.config({ path: path.resolve(__dirname, ".env.test") });

if (envResult.error) {
  // Only throw when the file is genuinely missing – not when it was already
  // loaded by a parent process or test runner.
  if (envResult.error.code === "ENOENT") {
    throw new Error(
      `[db] Could not find .env.test at ${path.resolve(__dirname, ".env.test")}. ` +
        "Please create the file and add DATABASE_URL."
    );
  }
  // Any other parse error is still fatal.
  throw new Error(`[db] Failed to parse .env.test: ${envResult.error.message}`);
}

// ---------------------------------------------------------------------------
// 2.  Validate the DATABASE_URL value before attempting to connect
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    "[db] DATABASE_URL is not defined. " +
      "Add DATABASE_URL=postgresql://<user>:<pass>@<host>:<port>/<dbname> to .env.test."
  );
}

// Basic sanity-check: the value must look like a postgres(ql):// URI.
const POSTGRES_URI_REGEX = /^postgr(es|esql):\/\/.+/i;
if (!POSTGRES_URI_REGEX.test(DATABASE_URL)) {
  throw new Error(
    `[db] DATABASE_URL does not look like a valid PostgreSQL connection string.\n` +
      `     Received: "${DATABASE_URL}"\n` +
      `     Expected format: postgresql://user:password@host:port/database`
  );
}

// ---------------------------------------------------------------------------
// 3.  Create the connection pool
// ---------------------------------------------------------------------------
const { Pool } = require("pg");

/**
 * Pool configuration.
 *
 * All values can be overridden by prefixing with PGPOOL_ in the environment
 * so that individual deployments can tune the pool without modifying code:
 *
 *   PGPOOL_MAX          – maximum number of clients (default 10)
 *   PGPOOL_IDLE_TIMEOUT – ms before an idle client is released (default 30 000)
 *   PGPOOL_CONN_TIMEOUT – ms to wait for a connection before throwing (default 5 000)
 *   PGPOOL_STATEMENT_TIMEOUT – ms before a query is automatically cancelled (default none)
 *   PGPOOL_SSL          – set to "true" to require TLS (default false)
 */
const poolConfig = {
  connectionString: DATABASE_URL,
  max: parseInt(process.env.PGPOOL_MAX ?? "10", 10),
  idleTimeoutMillis: parseInt(process.env.PGPOOL_IDLE_TIMEOUT ?? "30000", 10),
  connectionTimeoutMillis: parseInt(process.env.PGPOOL_CONN_TIMEOUT ?? "5000", 10),
  ...(process.env.PGPOOL_STATEMENT_TIMEOUT && {
    statement_timeout: parseInt(process.env.PGPOOL_STATEMENT_TIMEOUT, 10),
  }),
  ...(process.env.PGPOOL_SSL === "true" && {
    ssl: { rejectUnauthorized: false },
  }),
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// 4.  Pool-level error handler
//     "error" events on idle clients would otherwise crash the process.
// ---------------------------------------------------------------------------
pool.on("error", (err, client) => {
  console.error("[db] Unexpected error on idle PostgreSQL client:", err.message);
  console.error("[db] Stack:", err.stack);
  // Do NOT re-throw here – pg emits this on the pool, not on a request,
  // so there is no caller to propagate to.  Logging is sufficient; the pool
  // will remove the broken client automatically.
});

pool.on("connect", (client) => {
  if (process.env.NODE_ENV !== "test") {
    console.log("[db] New client connected to the pool.");
  }
});

pool.on("remove", (client) => {
  if (process.env.NODE_ENV !== "test") {
    console.log("[db] Client removed from the pool.");
  }
});

// ---------------------------------------------------------------------------
// 5.  query() — thin wrapper with structured error logging
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised SQL query using a pool-managed client.
 *
 * @param {string}  text   – SQL query string (use $1, $2 … for parameters)
 * @param {Array}   [params=[]] – array of parameter values
 * @returns {Promise<import('pg').QueryResult>}
 *
 * @example
 * const { rows } = await query('SELECT id, name FROM users WHERE id = $1', [42]);
 */
async function query(text, params = []) {
  if (typeof text !== "string" || text.trim() === "") {
    throw new TypeError("[db] query() requires a non-empty SQL string as its first argument.");
  }

  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    if (process.env.NODE_ENV !== "test") {
      console.log("[db] Executed query", {
        text,
        duration: `${duration}ms`,
        rowCount: result.rowCount,
      });
    }

    return result;
  } catch (err) {
    const duration = Date.now() - start;
    console.error("[db] Query failed:", {
      text,
      params,
      duration: `${duration}ms`,
      error: err.message,
      code: err.code,     // PostgreSQL error code, e.g. "42P01" (undefined_table)
      detail: err.detail, // PostgreSQL DETAIL field when available
    });
    // Re-throw so the caller can decide how to handle it.
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 6.  getClient() — checked-out client with automatic release on error
// ---------------------------------------------------------------------------

/**
 * Checks out a dedicated client from the pool.
 *
 * The returned client **must** be released when you are done with it –
 * call `client.release()`.  If an error is emitted on the client before
 * `release()` is called the client is destroyed automatically (the pool
 * will create a replacement on the next request).
 *
 * Use this function when you need to run multiple statements inside a
 * single transaction.
 *
 * @returns {Promise<import('pg').PoolClient>}
 *
 * @example
 * const client = await getClient();
 * try {
 *   await client.query('BEGIN');
 *   await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [100, 1]);
 *   await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [100, 2]);
 *   await client.query('COMMIT');
 * } catch (err) {
 *   await client.query('ROLLBACK');
 *   throw err;
 * } finally {
 *   client.release();
 * }
 */
async function getClient() {
  let client;

  try {
    client = await pool.connect();
  } catch (err) {
    console.error("[db] Failed to check out a client from the pool:", err.message);
    throw err;
  }

  // Wrap the native release so that if the client emits an error after being
  // returned to the caller (but before release) we automatically destroy it
  // rather than returning a broken client to the pool.
  const originalRelease = client.release.bind(client);
  let released = false;

  const safeRelease = (destroy = false) => {
    if (released) return;
    released = true;
    client.removeListener("error", onClientError);
    originalRelease(destroy);
  };

  const onClientError = (err) => {
    console.error("[db] Error emitted on checked-out client – destroying:", err.message);
    safeRelease(true); // destroy = true prevents returning broken client to pool
  };

  client.once("error", onClientError);

  // Expose the safe release under the standard name so callers don't need
  // to know about this wrapper.
  client.release = safeRelease;

  return client;
}

// ---------------------------------------------------------------------------
// 7.  healthCheck() — verify the database is reachable
// ---------------------------------------------------------------------------

/**
 * Sends a lightweight `SELECT 1` to the database and returns a structured
 * report.  Never throws — all failures are captured in the returned object
 * so callers can use this safely in readiness probes or monitoring endpoints.
 *
 * @returns {Promise<{
 *   healthy:       boolean,
 *   timestamp:     string,   // ISO-8601
 *   responseTimeMs: number,
 *   database:      string | null,  // current_database() value
 *   poolStats: {
 *     totalCount:   number,  // all clients (idle + active + pending)
 *     idleCount:    number,
 *     waitingCount: number,  // requests waiting for a free client
 *   },
 *   error?: string,          // only present when healthy === false
 * }>}
 *
 * @example
 * app.get('/healthz', async (req, res) => {
 *   const report = await healthCheck();
 *   res.status(report.healthy ? 200 : 503).json(report);
 * });
 */
async function healthCheck() {
  const start = Date.now();

  const report = {
    healthy: false,
    timestamp: new Date().toISOString(),
    responseTimeMs: 0,
    database: null,
    poolStats: {
      totalCount: pool.totalCount,
      idleCount: pool.idleCount,
      waitingCount: pool.waitingCount,
    },
  };

  try {
    const result = await pool.query("SELECT 1 AS ping, current_database() AS db_name");

    report.healthy = result.rows[0]?.ping === 1;
    report.database = result.rows[0]?.db_name ?? null;
    report.responseTimeMs = Date.now() - start;

    // Refresh pool stats after the query completes.
    report.poolStats = {
      totalCount: pool.totalCount,
      idleCount: pool.idleCount,
      waitingCount: pool.waitingCount,
    };
  } catch (err) {
    report.responseTimeMs = Date.now() - start;
