// Pool-level error handling
// ---------------------------------------------------------------------------
// Handles errors on idle clients — without this listener, an unexpected error
// on an idle client will throw and crash the process.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw here; let the pool manage reconnection.
});

pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised query using a pool-managed client.
 *
 * @param {string}  text   - Parameterised SQL string (e.g. `SELECT * FROM users WHERE id = $1`)
 * @param {Array}  [params] - Positional parameter values
 * @returns {Promise<pg.QueryResult>}
 *
 * @example
 * const { rows } = await query('SELECT * FROM users WHERE id = $1', [42]);
 */
export async function query(text, params = []) {
