 * Acquire a dedicated client from the pool for use within a transaction.
 * You MUST call `client.release()` in a finally block to avoid leaking the connection.
 *
 * @returns {Promise<pg.PoolClient>}
 *
 * @example
 * const client = await getClient();
 * try {
 *   await client.query('BEGIN');
 *   await client.query('INSERT INTO ...');
 *   await client.query('COMMIT');
 * } catch (err) {
 *   await client.query('ROLLBACK');
 *   throw err;
 * } finally {
 *   client.release();
 * }
 */
export async function getClient() {
  try {
    return await pool.connect();
  } catch (err) {
    console.error('[db] Failed to acquire client from pool:', err.message);
    throw err;
  }
}

