 * Health check — verifies the pool can reach the database.
 * Returns a structured result suitable for use in a /health endpoint.
 *
 * @returns {Promise<{ healthy: boolean, latencyMs: number|null, error: string|null }>}
 *
 * @example
 * app.get('/health/db', async (req, res) => {
 *   const result = await healthCheck();
 *   res.status(result.healthy ? 200 : 503).json(result);
 * });
 */
export async function healthCheck() {
  const start = Date.now();
  try {
    await pool.query('SELECT 1');
    return { healthy: true, latencyMs: Date.now() - start, error: null };
  } catch (err) {
    console.error('[db] Health check failed:', err.message);
    return { healthy: false, latencyMs: null, error: err.message };
  }
}

/**
 * Gracefully drain and close all pool connections.
 * Call this during process shutdown (SIGTERM/SIGINT).
 *
 * @returns {Promise<void>}
 */
export async function closePool() {
  console.log('[db] Closing connection pool…');
  await pool.end();
  console.log('[db] Pool closed.');
}

// ---------------------------------------------------------------------------
// Graceful shutdown hooks
// ---------------------------------------------------------------------------
process.once('SIGINT',  () => closePool().then(() => process.exit(0)));
process.once('SIGTERM', () => closePool().then(() => process.exit(0)));

export default pool;
