/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL at *runtime* from process.env (populated by
 * your environment or a tool like `dotenv`).  Credentials are never
 * hard-coded or committed to source control.
 *
 * Usage:
 *   const { query, healthCheck, pool } = require('./db');
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

// DATABASE_URL must be injected into the process environment *before* this
// module is loaded (e.g. via `dotenv.config({ path: '.env.test' })` in your
// entry-point or test setup file — never read the raw file here).
const connectionString = process.env.DATABASE_URL;

if (!connectionString) {
  throw new Error(
    '[db] DATABASE_URL is not set. ' +
    'Load your .env file before requiring this module (e.g. with dotenv).'
  );
}

// ---------------------------------------------------------------------------
// Pool creation
// ---------------------------------------------------------------------------

const pool = new Pool({
  connectionString,

  // Keep a small pool for typical web services; tune per workload.
  max: 10,               // maximum number of clients in the pool
  idleTimeoutMillis: 30_000,   // close idle clients after 30 s
  connectionTimeoutMillis: 5_000, // error if a connection cannot be obtained in 5 s
});

// ---------------------------------------------------------------------------
// Pool-level error handling
// ---------------------------------------------------------------------------

// Catches errors emitted by idle clients (e.g. unexpected disconnections).
// Without this listener an unhandled 'error' event would crash the process.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw here — the pool will remove the bad client automatically.
});

pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// Public helpers
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised SQL query.
 *
 * @param {string}  text   - SQL string with $1, $2 … placeholders.
 * @param {Array}   [params] - Parameter values (default: []).
 * @returns {Promise<import('pg').QueryResult>}
 *
 * @example
 *   const { rows } = await query('SELECT * FROM users WHERE id = $1', [42]);
 */
async function query(text, params = []) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log('[db] query executed', { text, duration, rows: result.rowCount });
    return result;
  } catch (err) {
    console.error('[db] query error', { text, error: err.message });
    throw err; // re-throw so callers can handle it
  }
}

/**
 * Acquire a dedicated client from the pool (for transactions).
 *
 * Always release the client in a finally block:
 *
 * @example
 *   const client = await getClient();
 *   try {
 *     await client.query('BEGIN');
 *     await client.query('INSERT INTO …');
 *     await client.query('COMMIT');
 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
async function getClient() {
  const client = await pool.connect();
  return client;
}

/**
 * Health check — verifies the pool can reach the database.
 *
 * Returns an object describing the outcome so callers can decide how to
 * surface the result (HTTP 200/503, log entry, etc.).
 *
 * @returns {Promise<{ healthy: boolean, latencyMs: number, message: string }>}
 *
 * @example
 *   app.get('/health/db', async (req, res) => {
 *     const status = await healthCheck();
 *     res.status(status.healthy ? 200 : 503).json(status);
 *   });
 */
async function healthCheck() {
  const start = Date.now();

