const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1.  Load environment variables from .env.test
//     dotenv.config() is a no-op when a variable is already set in the
//     process environment, so this is safe to call unconditionally.
// ---------------------------------------------------------------------------
const dotenv = require('dotenv');

const envResult = dotenv.config({
  path: path.resolve(__dirname, '.env.test'),
});

if (envResult.error) {
  // Treat a missing / unreadable .env.test file as a hard startup error so
  // the problem is obvious immediately rather than surfacing as a cryptic
  // "connection refused" later.
  throw new Error(
    `[db] Failed to load .env.test: ${envResult.error.message}`
  );
}

// ---------------------------------------------------------------------------
// 2.  Validate that DATABASE_URL was actually present in the file
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Make sure .env.test contains a valid DATABASE_URL entry.'
  );
}

// ---------------------------------------------------------------------------
// 3.  Build the connection pool
//
//     Pool configuration reference:
//       https://node-postgres.com/apis/pool
//
//     All values below are explicit defaults so the behaviour is clear when
//     reading the code without having to consult library documentation.
// ---------------------------------------------------------------------------
const POOL_CONFIG = {
  connectionString: DATABASE_URL,

  // Maximum number of clients kept open simultaneously.
  max: 10,

  // Milliseconds a client may sit idle before being closed and removed.
  idleTimeoutMillis: 30_000,

  // Milliseconds to wait for a client before throwing a timeout error.
  connectionTimeoutMillis: 5_000,

  // Keep SSL flexible: respect the connection-string flag but do not hard-
  // code a blanket "rejectUnauthorized: false" that would silently disable
  // certificate validation in production.
  ssl: DATABASE_URL.includes('sslmode=require')
    ? { rejectUnauthorized: true }
    : undefined,
};

const pool = new Pool(POOL_CONFIG);

// ---------------------------------------------------------------------------
// 4.  Pool-level error handler
//
//     pg emits 'error' on the Pool object whenever an *idle* client
//     encounters a connection problem (e.g. the server closes the socket
//     while the client is sitting in the pool).  Without this handler the
//     error would be an unhandled EventEmitter error and crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client', {
    message: err.message,
    code:    err.code,       // PostgreSQL error code when available
    client:  client ? 'present' : 'unavailable',
  });
  // Do NOT re-throw here — pg already removes the broken client from the
  // pool.  Throwing would crash the process unnecessarily.
});

// Convenience log so you can confirm which pool config is active.
pool.on('connect', () => {
  console.log('[db] New client connected to the pool');
});

