 * Verify that the pool can reach the database.
 *
 * Acquires a client, runs `SELECT 1` (the lightest valid Postgres query),
 * releases the client, and returns a structured status object.
 *
 * @returns {Promise<{
 *   status:      'healthy' | 'unhealthy',
 *   timestamp:   string,
 *   databaseUrl: string,
 *   latencyMs:   number | null,
 *   pool: {
 *     total:   number,
 *     idle:    number,
 *     waiting: number,
 *   },
 *   error: string | null,
 * }>}
 *
 * @example
 * app.get('/health/db', async (req, res) => {
 *   const report = await healthCheck();
 *   res.status(report.status === 'healthy' ? 200 : 503).json(report);
 * });
 */
async function healthCheck() {
  const timestamp = new Date().toISOString();

  // Redact credentials from the URL before including it in any output.
  // postgres://user:password@host:port/db  →  postgres://***@host:port/db
  const redactedUrl = DATABASE_URL.replace(
    /^(postgres(?:ql)?:\/\/)[^@]+@/,
    '$1***@'
  );

  // Snapshot pool stats *before* acquiring a client so they reflect the
  // ambient state rather than the state during the probe.
  const poolStats = {
    total:   pool.totalCount,
    idle:    pool.idleCount,
    waiting: pool.waitingCount,
  };

  let client;
  const start = Date.now();

  try {
    // connect() honours connectionTimeoutMillis set in POOL_CONFIG.
    client = await pool.connect();

    await client.query('SELECT 1');

    const latencyMs = Date.now() - start;

    return {
      status:      'healthy',
      timestamp,
      databaseUrl: redactedUrl,
      latencyMs,
      pool:        poolStats,
      error:       null,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;

    console.error('[db] Health check failed', {
      message: err.message,
      code:    err.code,
    });

    return {
      status:      'unhealthy',
      timestamp,
      databaseUrl: redactedUrl,
      latencyMs,
      pool:        poolStats,
      error:       err.message,
    };
  } finally {
    // Always release — even if client is undefined (connect() threw).
    if (client) {
      client.release();
    }
  }
