// ---------------------------------------------------------------------------
// 7.  Graceful shutdown helper
//
//     Call this in your SIGTERM / SIGINT handler to drain in-flight queries
//     and close all sockets cleanly.
// ---------------------------------------------------------------------------

/**
 * Drain the pool and close all connections.
 * Safe to call multiple times (subsequent calls are no-ops after pg resolves).
 *
 * @returns {Promise<void>}
 *
 * @example
 * process.on('SIGTERM', async () => {
 *   await closePool();
 *   process.exit(0);
 * });
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Connection pool closed.');
}

// ---------------------------------------------------------------------------
// 8.  Exports
// ---------------------------------------------------------------------------
module.exports = {
  /** The raw pg Pool — use sparingly; prefer query() for normal SQL work. */
  pool,

  /** Execute a parameterised SQL query and return the pg QueryResult. */
  query,

  /** Run a lightweight connectivity probe and return a status object. */
  healthCheck,

  /** Gracefully drain and close the pool (call on process shutdown). */
  closePool,
};

