/**
 * db.js
 *
 * PostgreSQL connection pool module.
 *
 * - Loads DATABASE_URL exclusively from .env.test via dotenv.
 * - Creates and exports a pg Pool instance.
 * - Attaches a pool-level error handler so idle-client errors never crash
 *   the process.
 * - Exports a healthCheck() function that runs a lightweight query and
 *   returns a structured result object.
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
// ---------------------------------------------------------------------------
const envPath = path.resolve(__dirname, '.env.test');
const envResult = dotenv.config({ path: envPath });

if (envResult.error) {
  throw new Error(
    `[db] Failed to load environment file at "${envPath}": ${envResult.error.message}`
  );
}

// ---------------------------------------------------------------------------
// 2. Validate the required DATABASE_URL variable
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Make sure it is set inside .env.test.'
  );
}

// ---------------------------------------------------------------------------
// 3. Build pool configuration from DATABASE_URL
//
//    All tuneable knobs are expressed here with sane defaults so they can be
//    overridden via environment variables without touching this file.
// ---------------------------------------------------------------------------
const poolConfig = {
  connectionString: DATABASE_URL,

  // Maximum number of clients kept alive in the pool (default: 10).
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client must sit idle before being evicted (default: 30 s).
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait for a new connection before throwing (default: 5 s).
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '5000',
    10
  ),

  // Maximum number of times a failed connection is retried (pg ≥ 8.9).
  // Setting this to 0 disables built-in retries so callers control retry logic.
  maxUses: parseInt(process.env.DB_MAX_USES ?? '7500', 10),
};

// ---------------------------------------------------------------------------
// 4. Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// 5. Pool-level error handler
//
//    The 'error' event fires when an idle client encounters a network error
//    (e.g. the database restarted).  Without a listener Node.js would throw
//    an uncaught exception and terminate the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  console.error('[db] Client details:', client?.connectionParameters?.host ?? 'unknown host');
  // Do NOT call process.exit() – let the pool recover by replacing the client.
});

// Emit a single log line when the first client successfully connects so
// operators can see the pool is alive in the startup logs.
pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

// ---------------------------------------------------------------------------
// 6. healthCheck()
//
//    Borrows one client, runs "SELECT 1 AS result", and immediately releases
//    it.  Returns a plain object so callers can decide how to handle the
//    result without coupling to pg internals.
//
//    Resolves:
//      { healthy: true,  responseTimeMs: <number>, serverVersion: <string> }
//
//    Rejects with:
//      { healthy: false, responseTimeMs: <number>, error: <string> }
// ---------------------------------------------------------------------------

/**
 * @typedef {Object} HealthCheckResult
 * @property {boolean} healthy          - Whether the database responded correctly.
 * @property {number}  responseTimeMs   - Round-trip time in milliseconds.
 * @property {string}  [serverVersion]  - PostgreSQL server_version string (healthy only).
 * @property {string}  [error]          - Error message (unhealthy only).
 */

/**
 * Runs a lightweight connectivity check against the database.
 *
 * @returns {Promise<HealthCheckResult>}
 */
