/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test (or the environment) using dotenv,
 * then creates a pg.Pool with sensible defaults.
 *
 * Usage:
 *   const { query, healthCheck, pool } = require('./db');
 *
 * Prerequisites:
 *   npm install pg dotenv
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op when a variable is already set in the process
//    environment, so .env.test values act as safe defaults for the test env.
// ---------------------------------------------------------------------------
const dotenv = require('dotenv');

const dotenvResult = dotenv.config({
  path: path.resolve(__dirname, '.env.test'),
});

if (dotenvResult.error) {
  // Non-fatal: the variable may already be in the process environment.
  console.warn(
    '[db] Warning: could not parse .env.test —',
    dotenvResult.error.message,
  );
}

// ---------------------------------------------------------------------------
// 2. Validate that DATABASE_URL is present before creating the pool.
//    Failing loudly here prevents cryptic connection errors later.
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
      'Ensure the variable exists in .env.test or in the process environment.',
  );
}

// ---------------------------------------------------------------------------
// 3. Create the connection pool.
//
//    Pool configuration explained:
//      connectionString – parsed from DATABASE_URL; includes host, port,
//                         user, password, and database name in one URI.
//      max              – upper bound on simultaneous client connections.
//      idleTimeoutMillis– how long an idle client stays in the pool before
//                         being closed (60 s is a safe default).
//      connectionTimeoutMillis – how long pool.connect() waits for an
//                         available client before rejecting (10 s).
//      allowExitOnIdle  – lets the Node process exit naturally when all
//                         clients are idle; useful in scripts / tests.
//
//    SSL:
//      In production, pass  ssl: { rejectUnauthorized: true }  (or load a
//      CA cert).  For a local or test database that does not use TLS, either
//      omit the key or set  ssl: false.  The environment variable
//      PGSSLMODE=disable also suppresses SSL without code changes.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '60000', 10),
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '10000',
    10,
  ),
  allowExitOnIdle: true,
});

// ---------------------------------------------------------------------------
// 4. Pool-level error handler.
//
//    pg emits an 'error' event on the pool when a connected client encounters
//    an unexpected error *while idle* (e.g. the database server closes the
//    socket).  Without this listener the error would be an unhandled event
//    and crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle PostgreSQL client:', err);
  // Do NOT re-throw here; the pool will automatically remove the broken
  // client and create a fresh one on the next request.
});

// ---------------------------------------------------------------------------
// 5. Optional lifecycle logging (useful during development / debugging).
// ---------------------------------------------------------------------------
pool.on('connect', () => {
  console.debug('[db] New client connected to PostgreSQL pool.');
});

pool.on('acquire', () => {
  console.debug('[db] Client acquired from pool.');
});

pool.on('remove', () => {
  console.debug('[db] Client removed from PostgreSQL pool.');
});

// ---------------------------------------------------------------------------
// 6. query() — thin wrapper around pool.query().
//
//    Centralises query execution so you can add logging, metrics, or
//    automatic retries in one place without touching every call-site.
//
//    @param {string}  text   – parameterised SQL string, e.g. 'SELECT $1'
//    @param {Array}   params – positional parameter values (optional)
//    @returns {Promise<import('pg').QueryResult>}
// ---------------------------------------------------------------------------
async function query(text, params = []) {
  const start = Date.now();
  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.debug('[db] Executed query', {
      text,
      duration: `${duration}ms`,
      rowCount: result.rowCount,
    });
    return result;
  } catch (err) {
    console.error('[db] Query error:', { text, error: err.message });
    throw err; // re-throw so callers can handle or propagate
  }
}

// ---------------------------------------------------------------------------
// 7. healthCheck() — verifies the pool can reach the database.
//
//    Acquires a dedicated client (bypassing the query wrapper so we can call
//    client.release() in the finally block regardless of outcome), runs a
//    trivial round-trip query, and returns a structured result object.
//
//    @returns {Promise<{
//      healthy: boolean,
//      timestamp: string,
//      latencyMs: number,
//      error?: string,
//    }>}
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();
  let client;

  try {
    // Acquire a client with a shorter deadline than the pool default so a
    // stalled health check does not block application health routes for long.
    client = await pool.connect();
    await client.query('SELECT 1');

    const latencyMs = Date.now() - start;
    console.debug(`[db] Health check passed in ${latencyMs}ms.`);

    return {
      healthy: true,
      timestamp: new Date().toISOString(),
      latencyMs,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;
    console.error('[db] Health check failed:', err.message);

    return {
      healthy: false,
      timestamp: new Date().toISOString(),
      latencyMs,
      error: err.message,
    };
  } finally {
    // Always release the client back to the pool, even on error.
    if (client) client.release();
  }
}

// ---------------------------------------------------------------------------
// 8. gracefulShutdown() — drains the pool cleanly on process exit.
//
//    Call this in SIGINT / SIGTERM handlers (see bottom of this file) or from
//    your application's shutdown sequence.
// ---------------------------------------------------------------------------
async function gracefulShutdown(signal = 'unknown') {
  console.info(`[db] Received ${signal}. Closing PostgreSQL pool…`);
  try {
    await pool.end();
    console.info('[db] PostgreSQL pool closed cleanly.');
  } catch (err) {
    console.error('[db] Error while closing pool:', err.message);
    process.exitCode = 1;
  }
}

// Register shutdown hooks so the pool is drained on normal process termination.
// Remove these lines if your application framework manages the lifecycle itself.
process.once('SIGINT', () => gracefulShutdown('SIGINT').then(() => process.exit()));
process.once('SIGTERM', () => gracefulShutdown('SIGTERM').then(() => process.exit()));

// ---------------------------------------------------------------------------
// 9. Public API
// ---------------------------------------------------------------------------
module.exports = {
  /** The underlying pg.Pool instance (use directly for transactions). */
  pool,
  /** Execute a SQL query against the pool. */
  query,
  /** Check that the database is reachable; returns a structured result. */
  healthCheck,
  /** Drain the pool before process exit. */
  gracefulShutdown,
};

