  "name": "pg-db-module",
  "version": "1.0.0",
  "description": "PostgreSQL connection pool module with health check",
  "main": "db.js",
  "scripts": {
    "test": "jest --runInBand --forceExit",
    "test:coverage": "jest --runInBand --forceExit --coverage"
  },
  "keywords": ["postgres", "pg", "database", "pool"],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "dotenv": "^16.4.5",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

/**
 * db.js
 *
 * PostgreSQL connection pool module.
 *
 * Reads DATABASE_URL from .env.test, creates a pg Pool with sensible
 * defaults, attaches a permanent error listener so unexpected client-level
 * errors never crash the process, and exports a healthCheck() helper that
 * verifies the pool can reach the database before the application starts.
 */

"use strict";

const path = require("path");
const { Pool } = require("pg");

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
// ---------------------------------------------------------------------------
const dotenv = require("dotenv");

const envResult = dotenv.config({ path: path.resolve(__dirname, ".env.test") });

if (envResult.error) {
  // Surface a clear message instead of a cryptic downstream failure.
  throw new Error(
    `[db] Failed to load .env.test: ${envResult.error.message}`
  );
}

// ---------------------------------------------------------------------------
// 2. Validate the required variable early so misconfiguration is obvious.
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    "[db] DATABASE_URL is not defined. " +
      "Make sure .env.test contains a valid DATABASE_URL entry."
  );
}

// ---------------------------------------------------------------------------
// 3. Pool configuration
//
//    All values can be overridden by setting the corresponding environment
//    variables; the defaults shown here are appropriate for most test / dev
//    scenarios.
//
//    connectionString – parsed directly from DATABASE_URL
//    ssl             – set NODE_ENV=production to enable SSL
//    max             – maximum number of clients in the pool          (default 10)
//    idleTimeoutMillis   – close idle clients after this many ms      (default 30 s)
//    connectionTimeoutMillis – throw if a client cannot be obtained   (default 5 s)
//    allowExitOnIdle – allow the Node process to exit when pool is idle
// ---------------------------------------------------------------------------
const poolConfig = {
  connectionString: DATABASE_URL,

  // Only enforce SSL outside of local/test environments.
  ssl:
    process.env.NODE_ENV === "production"
      ? { rejectUnauthorized: true }
      : false,

  max: parseInt(process.env.DB_POOL_MAX ?? "10", 10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT ?? "30000", 10),
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONN_TIMEOUT ?? "5000",
    10
  ),
  allowExitOnIdle: true,
};

// ---------------------------------------------------------------------------
// 4. Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// 5. Pool-level error handler
//
//    pg emits an "error" event on the pool when an idle client encounters an
//    unexpected error (e.g. the server closes the connection).  Without this
//    listener the error would be an unhandled EventEmitter exception and crash
//    the process.
// ---------------------------------------------------------------------------
pool.on("error", (err, client) => {
  console.error(
    "[db] Unexpected error on idle PostgreSQL client:",
    err.message
  );
  // Do NOT re-throw; log and let the pool recover.
});

// ---------------------------------------------------------------------------
// 6. Optional: log connect / remove events during development
// ---------------------------------------------------------------------------
if (process.env.NODE_ENV !== "test") {
  pool.on("connect", () => {
    console.log("[db] New client connected to the pool.");
  });

  pool.on("remove", () => {
    console.log("[db] Client removed from the pool.");
  });
}

// ---------------------------------------------------------------------------
// 7. healthCheck
//
//    Acquires a client, runs a lightweight `SELECT 1` query, then releases the
//    client back to the pool.  Returns a plain object with status information
//    so callers can decide how to surface the result (HTTP 200/503, logs, etc.)
//
//    @returns {Promise<{ healthy: boolean, timestamp: string, message: string,
//                        latencyMs: number }>}
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();

  try {
    const result = await pool.query("SELECT 1 AS health_check");

    // Verify the database actually returned the expected row.
    const row = result.rows[0];
    if (!row || row.health_check !== 1) {
      throw new Error("Unexpected response from health-check query.");
    }

    const latencyMs = Date.now() - start;

    return {
      healthy: true,
      timestamp: new Date().toISOString(),
      message: "Database connection is healthy.",
      latencyMs,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;

    console.error("[db] Health check failed:", err.message);

    return {
      healthy: false,
      timestamp: new Date().toISOString(),
      message: `Health check failed: ${err.message}`,
      latencyMs,
    };
  }
}

// ---------------------------------------------------------------------------
// 8. Graceful shutdown helper
//
//    Call pool.end() when the process exits so all idle clients are cleanly
//    closed and in-flight queries are given a chance to finish.
// ---------------------------------------------------------------------------
async function disconnect() {
  await pool.end();
  console.log("[db] Pool has been drained and all connections closed.");
}

// ---------------------------------------------------------------------------
// 9. Exports
// ---------------------------------------------------------------------------
module.exports = {
  /**
   * Execute a SQL query using a pool-managed client.
   * Thin wrapper around pool.query() for convenience.
   *
   * @param {string}  text   – parameterised SQL string
   * @param {Array}  [params] – query parameters
   * @returns {Promise<import('pg').QueryResult>}
   */
  query: (text, params) => pool.query(text, params),

  /**
   * Obtain a dedicated client from the pool.
   * Remember to call client.release() when done.
   *
   * @returns {Promise<import('pg').PoolClient>}
   */
  getClient: () => pool.connect(),

  /** Run a lightweight SELECT 1 to verify the connection is alive. */
  healthCheck,

  /** Drain the pool; call before process.exit() in production servers. */
  disconnect,

  /**
   * Expose the raw pool so callers can attach additional listeners or
   * inspect pool.totalCount / idleCount / waitingCount if needed.
   */
  pool,
};

/**
 * db.test.js
 *
 * Unit-tests for the db.js module.
 *
 * All PostgreSQL network calls are mocked so the suite runs without a real
 * database.  We validate:
 *   - environment loading (dotenv)
 *   - Pool construction and configuration
 *   - query() / getClient() delegation
 *   - healthCheck() – happy path, unexpected row, and error path
 *   - disconnect() (pool.end)
 *   - pool "error" event handler (no crash)
 *   - missing DATABASE_URL guard
 *   - missing .env.test guard
 */

"use strict";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Fully reset the module registry and re-import db.js after each tweak to
 * process.env or mock state so every test group starts from a clean slate.
 */
function freshRequireDb() {
  jest.resetModules();
  return require("./db");
}

// ---------------------------------------------------------------------------
// Top-level mocks (applied before any require())
// ---------------------------------------------------------------------------

// --- dotenv -----------------------------------------------------------------
jest.mock("dotenv", () => ({
  config: jest.fn(() => ({ parsed: { DATABASE_URL: "postgres://mock/db" } })),
}));

// --- pg Pool ----------------------------------------------------------------
// We capture the event listeners the module registers so we can trigger them
// in tests, and we control what pool.query / pool.connect / pool.end return.

const mockPoolQuery = jest.fn();
const mockPoolConnect = jest.fn();
const mockPoolEnd = jest.fn();
const mockPoolOn = jest.fn();

// Factory: returns a fresh mock Pool instance each time `new Pool()` is called.
const MockPool = jest.fn().mockImplementation(() => ({
  query: mockPoolQuery,
  connect: mockPoolConnect,
  end: mockPoolEnd,
  on: mockPoolOn,
}));

jest.mock("pg", () => ({ Pool: MockPool }));

// ---------------------------------------------------------------------------
// Shared setup: ensure DATABASE_URL is present before the normal test groups.
// ---------------------------------------------------------------------------
beforeEach(() => {
  process.env.DATABASE_URL = "postgres://mock-host:5432/mockdb";
  jest.clearAllMocks();
});

afterEach(() => {
  delete process.env.DATABASE_URL;
});

// ===========================================================================
// 1. Module bootstrap
// ===========================================================================
describe("Module bootstrap", () => {
  test("calls dotenv.config() with the path to .env.test", () => {
    const dotenv = require("dotenv");
    freshRequireDb();

    expect(dotenv.config).toHaveBeenCalledTimes(1);

    const calledPath = dotenv.config.mock.calls[0][0].path;
    expect(calledPath).toMatch(/\.env\.test$/);
  });

  test("creates a Pool with connectionString from DATABASE_URL", () => {
    freshRequireDb();

    expect(MockPool).toHaveBeenCalledTimes(1);
    const config = MockPool.mock.calls[0][0];
    expect(config.connectionString).toBe(process.env.DATABASE_URL);
  });

  test("pool config contains expected numeric defaults", () => {
    freshRequireDb();

    const config = MockPool.mock.calls[0][0];
    expect(config.max).toBe(10);
    expect(config.idleTimeoutMillis).toBe(30000);
    expect(config.connectionTimeoutMillis).toBe(5000);
  });

  test("registers an 'error' event listener on the pool", () => {
    freshRequireDb();

    const errorListenerCall = mockPoolOn.mock.calls.find(
      ([event]) => event === "error"
    );
    expect(errorListenerCall).toBeDefined();
  });

  test("'error' listener logs without rethrowing (no crash)", () => {
    freshRequireDb();

    const [, errorHandler] = mockPoolOn.mock.calls.find(
      ([event]) => event === "error"
    );

    const consoleSpy = jest
      .spyOn(console, "error")
      .mockImplementation(() => {});

    // Simulating the event should not throw.
    expect(() =>
      errorHandler(new Error("idle client died"), {})
    ).not.toThrow();

    expect(consoleSpy).toHaveBeenCalledWith(
      expect.stringContaining("[db]"),
      expect.stringContaining("idle client died")
    );

    consoleSpy.mockRestore();
  });
});

// ===========================================================================
// 2. Guard clauses
// ===========================================================================
describe("Guard clauses", () => {
  test("throws when dotenv.config() returns an error", () => {
    const dotenv = require("dotenv");
    dotenv.config.mockReturnValueOnce({ error: new Error("file not found") });

    expect(() => freshRequireDb()).toThrow(/Failed to load \.env\.test/);
  });

  test("throws when DATABASE_URL is missing from the environment", () => {
    delete process.env.DATABASE_URL;

    expect(() => freshRequireDb()).toThrow(/DATABASE_URL is not defined/);
  });
});

// ===========================================================================
// 3. query()
// ===========================================================================
describe("query()", () => {
  test("delegates to pool.query with text and params", async () => {
    const db = freshRequireDb();

    const fakeResult = { rows: [{ id: 1 }], rowCount: 1 };
    mockPoolQuery.mockResolvedValueOnce(fakeResult);

    const result = await db.query("SELECT * FROM users WHERE id = $1", [1]);

    expect(mockPoolQuery).toHaveBeenCalledWith(
      "SELECT * FROM users WHERE id = $1",
      [1]
    );
    expect(result).toBe(fakeResult);
  });

  test("propagates rejection from pool.query", async () => {
    const db = freshRequireDb();

    mockPoolQuery.mockRejectedValueOnce(new Error("connection refused"));

    await expect(db.query("SELECT 1")).rejects.toThrow("connection refused");
  });
});

// ===========================================================================
// 4. getClient()
// ===========================================================================
describe("getClient()", () => {
  test("calls pool.connect() and returns the client", async () => {
    const db = freshRequireDb();

    const fakeClient = { query: jest.fn(), release: jest.fn() };
    mockPoolConnect.mockResolvedValueOnce(fakeClient);

    const client = await db.getClient();

    expect(mockPoolConnect).toHaveBeenCalledTimes(1);
    expect(client).toBe(fakeClient);
  });

  test("propagates rejection when pool.connect() fails", async () => {
    const db = freshRequireDb();

    mockPoolConnect.mockRejectedValueOnce(new Error("pool exhausted"));

    await expect(db.getClient()).rejects.toThrow("pool exhausted");
  });
});

// ===========================================================================
// 5. healthCheck()
// ===========================================================================
describe("healthCheck()", () => {
  test("returns healthy:true with latencyMs when SELECT 1 succeeds", async () => {
    const db = freshRequireDb();

    mockPoolQuery.mockResolvedValueOnce({
      rows: [{ health_check: 1 }],
    });

    const result = await db.healthCheck();

    expect(result.healthy).toBe(true);
    expect(result.message).toMatch(/healthy/i);
    expect(typeof result.latencyMs).toBe("number");
    expect(result.latencyMs).toBeGreaterThanOrEqual(0);
    expect(result.timestamp).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });

  test("issues exactly SELECT 1 AS health_check", async () => {
    const db = freshRequireDb();

    mockPoolQuery.mockResolvedValueOnce({ rows: [{ health_check: 1 }] });
    await db.healthCheck();

    expect(mockPoolQuery).toHaveBeenCalledWith(
      "SELECT 1 AS health_check"
    );
  });

  test("returns healthy:false when query rejects", async () => {
    const db = freshRequireDb();

    const consoleSpy = jest
      .spyOn(console, "error")
      .mockImplementation(() => {});

    mockPoolQuery.mockRejectedValueOnce(new Error("timeout"));

    const result = await db.healthCheck();

    expect(result.healthy).toBe(false);
    expect(result.message).toMatch(/timeout/);
    expect(typeof result.latencyMs).toBe("number");

    consoleSpy.mockRestore();
  });

  test("returns healthy:false when query returns unexpected row", async () => {
    const db = freshRequireDb();

    const consoleSpy = jest
      .spyOn(console, "error")
      .mockImplementation(() => {});

    // Server returns an empty result set — should be treated as unhealthy.
    mockPoolQuery.mockResolvedValueOnce({ rows: [] });

    const result = await db.healthCheck();

    expect(result.healthy).toBe(false);
    expect(result.message).toMatch(/Unexpected response/);

    consoleSpy.mockRestore();
  });

  test("healthCheck does not throw even when pool is broken", async () => {
    const db = freshRequireDb();
    const consoleSpy = jest
      .spyOn(console, "error")
      .mockImplementation(() => {});

    mockPoolQuery.mockRejectedValueOnce(new Error("ECONNREFUSED"));

    await expect(db.healthCheck()).resolves.not.toThrow();

    consoleSpy.mockRestore();
  });
});

// ===========================================================================
// 6. disconnect()
// ===========================================================================
describe("disconnect()", () => {
  test("calls pool.end() and logs a confirmation message", async () => {
    const db = freshRequireDb();

    mockPoolEnd.mockResolvedValueOnce(undefined);
    const consoleSpy = jest
      .spyOn(console, "log")
      .mockImplementation(() => {});

    await db.disconnect();

    expect(mockPoolEnd).toHaveBeenCalledTimes(1);
    expect(consoleSpy).toHaveBeenCalledWith(
      expect.stringContaining("[db]")
    );

    consoleSpy.mockRestore();
  });

  test("propagates rejection from pool.end()", async () => {
    const db = freshRequireDb();

    mockPoolEnd.mockRejectedValueOnce(new Error("end failed"));

    await expect(db.disconnect()).rejects.toThrow("end failed");
  });
});

// ===========================================================================
// 7. Exported surface
// ===========================================================================
describe("Exported surface", () => {
  test("exports query, getClient, healthCheck, disconnect, and pool", () => {
    const db = freshRequireDb();

    expect(typeof db.query).toBe("function");
    expect(typeof db.getClient).toBe("function");
    expect(typeof db.healthCheck).toBe("function");
    expect(typeof db.disconnect).toBe("function");
    expect(db.pool).toBeDefined();
  });
});

