"use strict";

// ── Minimal stubs so we can exercise db.js logic without real pg / dotenv ──
const Module = require("module");
const originalLoad = Module._load.bind(Module);

// Pool mock state – properties replaced per-test
const events = {};
const pool = {
  query:   null,
  connect: null,
  end:     null,
  on(evt, fn) { events[evt] = fn; },
};
let lastPoolConfig = null;

Module._load = function (request, parent, isMain) {
  if (request === "dotenv") {
    return {
      config() {
        process.env.DATABASE_URL = "postgres://mock-host:5432/mockdb";
        return { parsed: { DATABASE_URL: process.env.DATABASE_URL } };
      },
    };
  }
  if (request === "pg") {
    return {
      Pool: class Pool {
        constructor(cfg) {
          lastPoolConfig = cfg;
          Object.assign(this, pool);
        }
      },
    };
  }
  return originalLoad(request, parent, isMain);
};

// ── Load the module under test ─────────────────────────────────────────────
const db = require("./db.js");

// ── Assertion helpers ──────────────────────────────────────────────────────
let passed = 0;
let failed = 0;

function assert(desc, condition) {
  if (condition) { console.log("  \u2713", desc); passed++; }
  else           { console.error("  \u2717", desc); failed++; }
}

function assertAsync(desc, fn) {
  return fn()
    .then(() => { console.log("  \u2713", desc); passed++; })
    .catch((e) => { console.error("  \u2717", desc, "\u2192", e.message); failed++; });
}

// ── Run all tests ──────────────────────────────────────────────────────────
async function runAll() {
  // ==========================================================================
  console.log("\n\u2500\u2500 1. Module bootstrap \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500");
  assert("Pool created with DATABASE_URL",
    lastPoolConfig.connectionString === "postgres://mock-host:5432/mockdb");
  assert("Default max = 10",            lastPoolConfig.max === 10);
  assert("Default idleTimeout = 30000", lastPoolConfig.idleTimeoutMillis === 30000);
  assert("Default connTimeout = 5000",  lastPoolConfig.connectionTimeoutMillis === 5000);
  assert("'error' listener registered", typeof events["error"] === "function");

  // ==========================================================================
  console.log("\n\u2500\u2500 2. Pool error listener \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500");
  let logged = "";
  const origErr = console.error;
  console.error = (...a) => { logged = a.join(" "); };
  let threw = false;
  try { events["error"](new Error("idle client died"), {}); }
  catch (e) { threw = true; }
  console.error = origErr;
  assert("Does not throw on pool error",  !threw);
  assert("Logs [db] prefix",              logged.includes("[db]"));
  assert("Logs error message",            logged.includes("idle client died"));

