  console.log("\n\u2500\u2500 3. Exports \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500");
  assert("exports query",       typeof db.query       === "function");
  assert("exports getClient",   typeof db.getClient   === "function");
  assert("exports healthCheck", typeof db.healthCheck === "function");
  assert("exports disconnect",  typeof db.disconnect  === "function");
  assert("exports pool",        db.pool !== undefined);

