    const fakeClient = { release: () => {} };
    pool.connect = () => Promise.resolve(fakeClient);
    const c = await db.getClient();
    if (c !== fakeClient) throw new Error("wrong client returned");
  });

  await assertAsync("propagates pool.connect rejection", async () => {
    pool.connect = () => Promise.reject(new Error("pool exhausted"));
    let caught = false;
    try { await db.getClient(); } catch (e) { if (e.message === "pool exhausted") caught = true; }
    if (!caught) throw new Error("rejection not propagated");
  });

