    if (!r.healthy)                      throw new Error("expected healthy:true");
    if (typeof r.latencyMs !== "number") throw new Error("missing latencyMs");
    if (!r.timestamp.match(/^\d{4}/))    throw new Error("bad timestamp");
    if (!r.message.match(/healthy/i))    throw new Error("bad message");
  });

  await assertAsync("issues SELECT 1 AS health_check", async () => {
    let capturedSQL;
    pool.query = (t) => { capturedSQL = t; return Promise.resolve({ rows: [{ health_check: 1 }] }); };
    await db.healthCheck();
    if (capturedSQL !== "SELECT 1 AS health_check") throw new Error("wrong SQL: " + capturedSQL);
  });

  await assertAsync("healthy:false when query rejects", async () => {
    pool.query = () => Promise.reject(new Error("ECONNREFUSED"));
    const ce = console.error; console.error = () => {};
    const r = await db.healthCheck();
    console.error = ce;
    if (r.healthy)                           throw new Error("should be unhealthy");
    if (!r.message.includes("ECONNREFUSED")) throw new Error("message missing error");
    if (typeof r.latencyMs !== "number")     throw new Error("missing latencyMs");
  });

  await assertAsync("healthy:false on unexpected row (empty rows[])", async () => {
    pool.query = () => Promise.resolve({ rows: [] });
    const ce = console.error; console.error = () => {};
    const r = await db.healthCheck();
    console.error = ce;
    if (r.healthy)                         throw new Error("should be unhealthy");
    if (!r.message.includes("Unexpected")) throw new Error("message missing");
  });

  await assertAsync("healthCheck never throws even on broken pool", async () => {
    pool.query = () => Promise.reject(new Error("broken"));
    const ce = console.error; console.error = () => {};
    try { await db.healthCheck(); }
    finally { console.error = ce; }
    // reaching here means no throw
  });

  // ==========================================================================
  console.log("\n\u2500\u2500 7. disconnect() \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500");
  await assertAsync("calls pool.end()", async () => {
    let called = false;
    pool.end = () => { called = true; return Promise.resolve(); };
    const cl = console.log; console.log = () => {};
    await db.disconnect();
    console.log = cl;
    if (!called) throw new Error("pool.end not called");
  });

  await assertAsync("logs a confirmation message with [db] prefix", async () => {
    pool.end = () => Promise.resolve();
    let msg = "";
    const cl = console.log; console.log = (...a) => { msg += a.join(" "); };
    await db.disconnect();
