    pool.end = () => Promise.reject(new Error("end failed"));
    let caught = false;
    try { await db.disconnect(); } catch (e) { if (e.message === "end failed") caught = true; }
    if (!caught) throw new Error("rejection not propagated");
  });

  // ==========================================================================
  console.log("\n\u2500\u2500 8. Guard clauses (fresh module instances) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500");

  // Guard: DATABASE_URL missing
  {
    const savedURL = process.env.DATABASE_URL;
    delete process.env.DATABASE_URL;

    const stubLoad = (req, par, isMain) => {
      if (req === "dotenv") return { config() { return { parsed: {} }; } };
      if (req === "pg")     return { Pool: class { constructor() {} on() {} } };
      return originalLoad(req, par, isMain);
    };
    Module._load = stubLoad;

