    };
    process.env.DATABASE_URL = savedURL;
    delete require.cache[require.resolve("./db.js")];

    assert("Throws when DATABASE_URL is missing", threw2);
    assert("Error message mentions DATABASE_URL",  msg2.includes("DATABASE_URL"));
  }

