  {
    const savedURL = process.env.DATABASE_URL;

    Module._load = function (req, par, isMain) {
      if (req === "dotenv") return { config() { return { error: new Error("no such file") }; } };
      if (req === "pg")     return { Pool: class { constructor() {} on() {} } };
      return originalLoad(req, par, isMain);
    };

    let threw3 = false, msg3 = "";
    try {
      delete require.cache[require.resolve("./db.js")];
      require("./db.js");
    } catch (e) { threw3 = true; msg3 = e.message; }

    // Restore normal stubs
    Module._load = function (req, par, isMain) {
      if (req === "dotenv") {
        return { config() { process.env.DATABASE_URL = savedURL; return { parsed: {} }; } };
      }
      if (req === "pg") {
        return { Pool: class Pool { constructor(cfg) { lastPoolConfig = cfg; Object.assign(this, pool); } } };
      }
      return originalLoad(req, par, isMain);
    };
    process.env.DATABASE_URL = savedURL;
    delete require.cache[require.resolve("./db.js")];

    assert("Throws when dotenv returns an error", threw3);
    assert("Error message mentions .env.test",    msg3.includes(".env.test"));
  }

  // ==========================================================================
  console.log("\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550");
  console.log(`Results: ${passed} passed, ${failed} failed`);
  if (failed > 0) process.exit(1);
}

runAll().catch((e) => { console.error("Unexpected error:", e); process.exit(1); });

