'use strict';

/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test (via dotenv) and exposes:
 *   - pool      : the pg.Pool instance for direct query use
 *   - query()   : a thin wrapper around pool.query()
 *   - healthCheck() : verifies the pool can reach the database
 *   - closePool()   : gracefully drains and closes all connections
 */

const path = require('path');
const { Pool } = require('pg');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    Override is set to false so that variables already present in process.env
//    (e.g. set by CI) take precedence over the file values.
// ---------------------------------------------------------------------------
const envResult = dotenv.config({
  path: path.resolve(__dirname, '.env.test'),
  override: false,
});

if (envResult.error) {
  // Not a fatal error — the variable may have been injected by the host OS.
  console.warn(
    '[db] Warning: could not load .env.test —',
    envResult.error.message,
  );
}

// ---------------------------------------------------------------------------
// 2. Validate that DATABASE_URL is present before trying to connect
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
      'Ensure it is set in .env.test or in the process environment.',
  );
}

// ---------------------------------------------------------------------------
// 3. Create the connection pool
//
//    All tuneable values have sensible defaults that can be overridden via
//    environment variables so no code changes are needed between environments.
//
//    connectionTimeoutMillis – how long to wait for a free connection from
//      the pool before throwing (default: 0 = wait forever).
//    idleTimeoutMillis – how long a client may sit idle before being closed
//      and removed from the pool (default: 10 000 ms).
//    max – maximum number of clients in the pool (default: 10).
//    ssl – disabled unless DATABASE_SSL=true, which is the safe default for
//      local / test environments while remaining easy to enable in production.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,
  max: parseInt(process.env.DATABASE_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(
    process.env.DATABASE_IDLE_TIMEOUT_MS ?? '10000',
    10,
  ),
  connectionTimeoutMillis: parseInt(
    process.env.DATABASE_CONNECT_TIMEOUT_MS ?? '5000',
    10,
  ),
  ssl:
    process.env.DATABASE_SSL === 'true'
      ? { rejectUnauthorized: true }
      : false,
});

// ---------------------------------------------------------------------------
// 4. Pool-level error handler
//
//    pg emits an 'error' event on the pool (not on individual queries) when a
//    client encounters an unexpected error while sitting idle.  Without this
//    listener the event would be an unhandled EventEmitter error and crash the
//    process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw here — crashing the process for an idle-client error is
  // almost never the right behaviour.  Let the caller's next query surface a
  // fresh error through the normal promise/callback path instead.
});

pool.on('connect', (client) => {
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', (client) => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// 5. query() — thin wrapper that checks out a client, runs the query,
//    and returns it to the pool automatically via pool.query()
//
//    @param {string}  text   - Parameterised SQL string, e.g. 'SELECT $1::text'
//    @param {Array}   [params] - Bound parameter values
//    @returns {Promise<pg.Result>}
// ---------------------------------------------------------------------------
async function query(text, params) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new TypeError('[db] query(): first argument must be a non-empty SQL string.');
  }

  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log('[db] Executed query:', {
      text: text.slice(0, 120), // truncate to avoid logging sensitive data
      duration: `${duration}ms`,
      rows: result.rowCount,
    });
    return result;
  } catch (err) {
    const duration = Date.now() - start;
    console.error('[db] Query failed:', {
      text: text.slice(0, 120),
      duration: `${duration}ms`,
      error: err.message,
    });
    throw err; // re-throw so callers can handle or propagate
  }
}

// ---------------------------------------------------------------------------
// 6. healthCheck() — acquires a dedicated client and runs a lightweight
//    round-trip query to confirm the database is reachable and responding.
//
//    Returns an object rather than just true/false so callers (e.g. a /health
//    HTTP endpoint) can surface timing and server version information.
//
//    @returns {Promise<{
//      healthy: boolean,
//      latencyMs: number,
//      serverVersion: string,
//      timestamp: string,
//      error?: string
//    }>}
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();

  let client;
  try {
    // connect() respects connectionTimeoutMillis set on the pool
    client = await pool.connect();

    const { rows } = await client.query(
      "SELECT version() AS server_version, NOW() AS server_time",
    );

    const latencyMs = Date.now() - start;
    const { server_version, server_time } = rows[0];

    console.log(`[db] Health check passed (${latencyMs}ms).`);

    return {
      healthy: true,
      latencyMs,
      serverVersion: server_version,
      timestamp: server_time,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;
    console.error(`[db] Health check failed (${latencyMs}ms):`, err.message);

    return {
      healthy: false,
      latencyMs,
      serverVersion: null,
      timestamp: null,
      error: err.message,
    };
  } finally {
    // Always release the client back to the pool, even on error
    if (client) {
      client.release();
    }
  }
}

// ---------------------------------------------------------------------------
// 7. closePool() — gracefully drains the pool
//
//    Call this during application shutdown (SIGTERM / SIGINT) to allow
//    in-flight queries to complete and connections to close cleanly.
//
//    @returns {Promise<void>}
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[db] Closing connection pool…');
  try {
    await pool.end();
    console.log('[db] Pool closed successfully.');
  } catch (err) {
    console.error('[db] Error while closing pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 8. Graceful shutdown on process termination signals
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.log(`[db] Received ${signal}. Initiating graceful shutdown.`);
  await closePool();
  process.exit(0);
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// 9. Exports
// ---------------------------------------------------------------------------
module.exports = {
  /** The underlying pg.Pool — use for transactions or advanced use-cases. */
  pool,

  /** Run a single parameterised query and return the pg.Result. */
  query,

  /**
   * Verify database connectivity.
   * Resolves to { healthy, latencyMs, serverVersion, timestamp, error? }.
   */
  healthCheck,

  /** Drain and close the pool.  Call during graceful shutdown. */
  closePool,
};

