    console.log('[db] Executed query:', {
      text: text.slice(0, 120), // truncate to avoid logging sensitive data
      duration: `${duration}ms`,
      rows: result.rowCount,
    });
    return result;
  } catch (err) {
    const duration = Date.now() - start;
    console.error('[db] Query failed:', {
      text: text.slice(0, 120),
      duration: `${duration}ms`,
      error: err.message,
    });
    throw err; // re-throw so callers can handle or propagate
  }
}

// ---------------------------------------------------------------------------
// 6. healthCheck() — acquires a dedicated client and runs a lightweight
//    round-trip query to confirm the database is reachable and responding.
//
//    Returns an object rather than just true/false so callers (e.g. a /health
//    HTTP endpoint) can surface timing and server version information.
//
//    @returns {Promise<{
//      healthy: boolean,
//      latencyMs: number,
//      serverVersion: string,
//      timestamp: string,
//      error?: string
//    }>}
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();

  let client;
  try {
    // connect() respects connectionTimeoutMillis set on the pool
    client = await pool.connect();

    const { rows } = await client.query(
      "SELECT version() AS server_version, NOW() AS server_time",
    );

    const latencyMs = Date.now() - start;
    const { server_version, server_time } = rows[0];

    console.log(`[db] Health check passed (${latencyMs}ms).`);

    return {
      healthy: true,
      latencyMs,
      serverVersion: server_version,
      timestamp: server_time,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;
    console.error(`[db] Health check failed (${latencyMs}ms):`, err.message);

    return {
      healthy: false,
      latencyMs,
      serverVersion: null,
      timestamp: null,
      error: err.message,
    };
  } finally {
    // Always release the client back to the pool, even on error
    if (client) {
      client.release();
    }
  }
}

// ---------------------------------------------------------------------------
// 7. closePool() — gracefully drains the pool
//
//    Call this during application shutdown (SIGTERM / SIGINT) to allow
//    in-flight queries to complete and connections to close cleanly.
//
//    @returns {Promise<void>}
// ---------------------------------------------------------------------------
async function closePool() {
  console.log('[db] Closing connection pool…');
  try {
    await pool.end();
    console.log('[db] Pool closed successfully.');
  } catch (err) {
    console.error('[db] Error while closing pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 8. Graceful shutdown on process termination signals
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.log(`[db] Received ${signal}. Initiating graceful shutdown.`);
  await closePool();
  process.exit(0);
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// 9. Exports
// ---------------------------------------------------------------------------
module.exports = {
  /** The underlying pg.Pool — use for transactions or advanced use-cases. */
  pool,

  /** Run a single parameterised query and return the pg.Result. */
  query,

  /**
   * Verify database connectivity.
   * Resolves to { healthy, latencyMs, serverVersion, timestamp, error? }.
   */
  healthCheck,

  /** Drain and close the pool.  Call during graceful shutdown. */
  closePool,
};
